    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span> حيث <span dir=\"ltr\" class=\"expr\">A = -4 - (x - 13) - [9 - (y + 5)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = -3</span> و <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = -3</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 4</span> و <span dir=\"ltr\" class=\"expr\">x = -9</span> <span dir=\"ltr\" class=\"expr\">A = -4 - (x - 13) - [9 - (y + 5)]</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = -3</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 4</span> و <span dir=\"ltr\" class=\"expr\">x = -9</span> <span dir=\"ltr\" class=\"expr\">x - y = 9</span> <span dir=\"ltr\" class=\"expr\">A = y - x + 5</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 13) = -x + 13</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [9 - (y + 5)] = -9 + y + 5</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - x + 13 - 9 + y + 5</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-4 + 13 - 9 + 5)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 13 - 9 + 5 = 5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 5</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(y - x) + 5 = -3</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">y - x = (-3) - 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y - x = -8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 5</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 4</span> و <span dir=\"ltr\" class=\"expr\">x = -9</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 4 - (-9) + 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 18</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 5</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = -9</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) + 5</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-9) + 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -4</span>"}],
