    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = -7 - |-9 + 4| + |-9 - 2| + |-9| + 1</span>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|-9 + 4| = 5</span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|-9 - 2| = 11</span>"},{"quoi":"القيمة المطلقة الثالثة","math":"<span dir=\"ltr\" class=\"expr\">|-9| = 9</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">A = -7 - 5 + 11 + 9 + 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 9</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 1) + (-1 - y)] = x - y + 1 + 1 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -4 - x + z + y + x - y + 1 + 1 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-4 + 1 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 1 + 1 = -2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z - 2</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z - 2</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">z = -6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = (-9) + (-6) - 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = -17</span>"}],
