    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - |-2 + 5| + |-2 - 7| + |-2| + 6</span>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|-2 + 5| = 3</span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|-2 - 7| = 9</span>"},{"quoi":"القيمة المطلقة الثالثة","math":"<span dir=\"ltr\" class=\"expr\">|-2| = 2</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - 3 + 9 + 2 + 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 10</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 2) + (-6 - y)] = x - y + 2 + 6 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -5 - x + z + y + x - y + 2 + 6 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-5 + 2 + 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 + 2 + 6 = 3</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 3</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">z = -5</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = 6 + (-5) + 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = 4</span>"}],
