    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">7 + [-3 - x] = -5</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">3 + x = -4</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">8 - (4 - x) = -4</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">x - 6 = 8</span><br><span class=\"q\">5) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-12 - |x| = 4</span><br><span class=\"q\">6) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-9 + (|x| - 9) = -4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">7 + -3 - x = -5</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 + (-3) = 4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 - x = -5</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 4 - (-5)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 - (-5) = 9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 9</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">7 + [-3 - 9] = -5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-4) - 3</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - 3 = -7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -7</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">3 + (-7) = -4</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">8 - 4 + x = -4</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">8 - 4 = 4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 + x = -4</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-4) - 4</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - 4 = -8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -8</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">8 - (4 - (-8)) = -4</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = 8 + 6</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">8 + 6 = 14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 14</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">14 - 6 = 8</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-12) - 4</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-12) - 4 = -16</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-16 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">-9 + |x| - 9 = -4</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-9 - 9 = -18</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-18 + |x| = -4</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-4) - (-18)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - (-18) = 14</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">14 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 14</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -14</span>"}],
