    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 11) = -x + 11</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [4 - (y + 1)] = -4 + y + 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -8 - x + 11 - 4 + y + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-8 + 11 - 4 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-8 + 11 - 4 + 1 = 0</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(y - x) + 0 = 6</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">y - x = 6 - 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y - x = 6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 3</span> و <span dir=\"ltr\" class=\"expr\">x = 7</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 3 - 7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -4</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = 12</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) + 0</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 12 + 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 12</span>"}],
