    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span> حيث <span dir=\"ltr\" class=\"expr\">A = -4 - (x - 5) - [7 - (y + 2)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 14</span> و <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 14</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = -3</span> <span dir=\"ltr\" class=\"expr\">A = -4 - (x - 5) - [7 - (y + 2)]</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 14</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = -3</span> <span dir=\"ltr\" class=\"expr\">x - y = -10</span> <span dir=\"ltr\" class=\"expr\">A = y - x - 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 5) = -x + 5</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [7 - (y + 2)] = -7 + y + 2</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - x + 5 - 7 + y + 2</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-4 + 5 - 7 + 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + 5 - 7 + 2 = -4</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 4</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 4</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(y - x) - 4 = 14</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">y - x = 14 - (-4)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y - x = 18</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 4</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = -3</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-9) - (-3) - 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -10</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 4</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = 10</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) - 4</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 10 - 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 6</span>"}],
