    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span> حيث <span dir=\"ltr\" class=\"expr\">A = -11 - (x - 15) - [3 - (y + 3)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 11</span> و <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 11</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">x = 1</span> <span dir=\"ltr\" class=\"expr\">A = -11 - (x - 15) - [3 - (y + 3)]</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 11</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">x = 1</span> <span dir=\"ltr\" class=\"expr\">x - y = 9</span> <span dir=\"ltr\" class=\"expr\">A = y - x + 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 15) = -x + 15</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [3 - (y + 3)] = -3 + y + 3</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -11 - x + 15 - 3 + y + 3</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-11 + 15 - 3 + 3)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-11 + 15 - 3 + 3 = 4</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 4</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 4</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(y - x) + 4 = 11</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">y - x = 11 - 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y - x = 7</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 4</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">x = 1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = 6 - 1 + 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 9</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 4</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = -9</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) + 4</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-9) + 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -5</span>"}],
